# ---------------------------------------------------------------- cards
def card(id, type, front, back, sec, core, src, img=None, spot=None, imgs=None):
    c = {"id": id, "type": type, "front": front, "back": back, "section_id": sec, "core": core, "source_ids": src}
    if img: c["image_id"] = img
    if imgs: c["image_ids"] = imgs
    if spot: c["spotlight_id"] = spot
    return c

