# ---------------------------------------------------------------- quiz bank (section checks)
def q(id, type, prompt, answer, expl, src, sec, spot=None, diff=2, **kw):
    d = {"id": id, "type": type, "prompt": prompt, "answer": answer, "explanation": expl, "source_ids": src, "section_id": sec, "spotlight_id": spot, "difficulty": diff}
    d.update(kw); return d

