import json, os, re
ROOT = os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", ".."))
OUT = os.path.join(ROOT, "data", "days", "0833.json")

def build():
    recs = {}
    if True:
        for r in IMAGE_RECORDS:
            if r.get("title") and not r.get("error") and r.get("free", True):
                recs[r["title"]] = r
    images = []
    for iid, title, alt, cap in IMGS + IMGS_EXTRA:
        r = recs.get(title)
        if not r: continue
        rec = {k: r[k] for k in ["url", "thumb_url", "width", "height", "author", "license", "license_url", "file_page", "attribution", "verified_on"]}
        rec = {"id": iid, **rec, "alt": alt, "caption": cap}
        images.append(rec)
    have = {i["id"] for i in images}
    verification = list(VERIFICATION)
    sections = []
    for n, s in enumerate(SECTIONS, 1):
        s = dict(s); s["order"] = n
        v = s.get("visual")
        if v and v.get("type") == "photo_grid":
            v["data"]["image_ids"] = [i for i in v["data"]["image_ids"] if i in have]
        if v and v.get("type") == "compare":
            for side in ("left", "right"):
                if v["data"][side].get("image_id") not in have: v["data"][side].pop("image_id", None)
        if v is None: s.pop("visual")
        spots = []
        for sp in s["spotlights"]:
            sp = dict(sp)
            sp["image_ids"] = [i for i in sp["image_ids"] if i in have][:3]
            if not sp["image_ids"]:
                verification.append({"claim": f"Photo for {sp['name']}", "status": "no_image", "note": "No openly licensed Commons image that shows this specific thing was found; left without a picture rather than use a generic one.", "spotlight_id": sp["id"]})
            if sp.get("compare", {}).get("image_id") and sp["compare"]["image_id"] not in have: sp["compare"].pop("image_id")
            spots.append(sp)
        s["spotlights"] = spots
        sections.append(s)
    cards = []
    for c in CARDS:
        c = dict(c)
        if c.get("image_ids"):
            c["image_ids"] = [i for i in c["image_ids"] if i in have]
        if c.get("image_id") and c["image_id"] not in have:
            c.pop("image_id"); c["type"] = "fact"
        cards.append(c)
    quiz = []
    for x in QUIZ:
        if x["type"] == "image_id" and x.get("image_id") not in have: continue
        if x["type"] == "compare" and not all(i in have for i in x.get("image_ids", [])): continue
        quiz.append(x)
    side = dict(SIDE); side["image_ids"] = [i for i in side["image_ids"] if i in have]
    sources = SOURCES + [{"id": i, "title": t, "url": u, "publisher": p, "accessed": ACC} for i, t, u, p in EXTRA_SOURCES]
    words = 0
    w = lambda t: len(re.findall(r"\w+", t or ""))
    for s in sections:
        words += w(s["intro_md"]) + sum(w(sp["story_md"]) + w(sp["spot_it"]) + w(sp["memory_hook"]) for sp in s["spotlights"])
    d = {
        "schema_version": 2, "id": "t0833", "day": 833, "area": "Economics", "title": "Behavioural economics: what it changed",
        "native_name": None, "as_of": "2026-10-25", "reading_minutes": max(45, min(60, round(words / 160))),
        "hero": HERO if HERO["image_id"] in have else {**HERO, "image_id": images[0]["id"]},
        "geo": None, "stats": STATS, "prequestions": PRE, "sections": sections, "cards": cards, "quiz": quiz, "quiz_bank": QUIZ_BANK,
        "images": images, "media": MEDIA, "sources": sources, "verification": verification,
        "best_facts": sorted(BEST, key=lambda f: -f["score"]), "side_dish": side, "offline_task": OFFLINE,
    }
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    json.dump(d, open(OUT, "w"), ensure_ascii=False, indent=1)
    print("wrote", OUT, "words~", words, "images", len(images))

if __name__ == "__main__":
    build()
